{
  "description": "The creature is a large quadrupedal mammal shown in right profile against a plain off-white background, standing on four thick legs. Its overall body shape, dense long shaggy brown fur, short stub tail, and head shape are bear-like, with lighter tan fur on the muzzle and chest and darker brown on the lower legs. On its dorsal side are two large, smooth, glossy, dark reddish-brown hardened shell sections resembling beetle elytra, one covering the shoulder area and one covering the mid-back to hindquarters. A single large glossy dark brown to black curved horn projects from the forehead. The outer sides of the forelegs bear smaller overlapping glossy segmented plates of the same dark color, and a row of small circular holes is visible in the fur along the side below the rear shell. The feet are broad paws with light-colored claws.",
  "parts": [
    {
      "part": "head",
      "looks_like": "bear-like, covered in shaggy brown fur with a lighter tan muzzle, black nose, small dark eyes with visible highlights, and fine whiskers on the muzzle",
      "where": "at the front of the body, viewed in right profile, with the nose pointing to the right"
    },
    {
      "part": "horns",
      "looks_like": "one large, smooth, glossy, dark brown to black curved horn that tapers to a sharp tip and has a small pointed tooth on its inner curve near the middle",
      "where": "arising from the center of the forehead on top of the head between the ears, curving upward and forward"
    },
    {
      "part": "ears",
      "looks_like": "two small, rounded, furry brown ears with dense fur",
      "where": "on top of the head, one on each side of the base of the horn"
    },
    {
      "part": "legs",
      "looks_like": "four thick, sturdy, columnar legs covered in long shaggy brown fur that is darker on the lower portions and lighter on the chest and inner areas",
      "where": "two forelegs under the shoulder and two hindlegs under the hips, supporting the body from below"
    },
    {
      "part": "feet",
      "looks_like": "four large broad paws with dense fur and five visible light tan to gray curved claws on each front paw and on the visible hind paws",
      "where": "at the bottom ends of each leg, in contact with the ground"
    },
    {
      "part": "tail",
      "looks_like": "a very short, small, rounded stub covered in brown fur",
      "where": "at the extreme rear of the body, barely protruding from the fur on the rump"
    },
    {
      "part": "shell",
      "looks_like": "two large, smooth, highly glossy, dark reddish-brown hardened plates with fine longitudinal lines and irregular crack-like divisions, resembling beetle elytra",
      "where": "on the back: one smaller shield-shaped plate over the shoulders behind the neck, and one larger oval plate over the mid-back and hindquarters"
    },
    {
      "part": "plates",
      "looks_like": "small, overlapping, glossy, dark reddish-brown segmented chitinous plates with pointed outer edges, arranged in rows",
      "where": "on the outer front sides of both forelegs, just above the paws"
    },
    {
      "part": "markings",
      "looks_like": "a row of eight small circular holes with dark centers and light rims, resembling spiracles, set in the fur",
      "where": "in a horizontal line along the side of the body just below the lower edge of the larger rear shell, between the mid-body and hind leg"
    }
  ],
  "attached_objects": [],
  "animals": ["bear", "beetle"],
  "separate_bodies": 1,
  "heads": 1,
  "walking_legs": 4,
  "wings": 0,
  "extra_limb_pieces": 0,
  "tails": 1
}
